import{_ as o,l as s,o as r,c as i,v as d,p as A,x as t,d as l,i as h,S as p,b as e}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"跨层 KV 共享 CLA","description":"","frontmatter":{"title":"跨层 KV 共享 CLA","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cross-layer-kv-sharing.md","filePath":"llm/cross-layer-kv-sharing.md","lastUpdated":1789023840000}'),c={name:"llm/cross-layer-kv-sharing.md"};function m(V,a,E,u,L,B){const n=s("Mermaid");return r(),i("div",null,[a[1]||(a[1]=d('<h1 id="跨层-kv-共享-cla" tabindex="-1">跨层 KV 共享 CLA <a class="header-anchor" href="#跨层-kv-共享-cla" aria-label="Permalink to &quot;跨层 KV 共享 CLA&quot;">​</a></h1><div class="epigraph"><p>相邻层读同一份键值，缓存按层数线性涨的那条腿被砍短；查询仍按层计算。</p><footer>—— Brandon et al., Reducing Transformer Key-Value Cache Size with Cross-Layer Attention, 2024</footer></div><p><a href="/llm/softmax-alternatives">上一课</a>把层内归一化当成可换模块。推理真正涨内存的往往不是 softmax 形态，而是每层一份 KV。<a href="/llm/gqa">分组查询</a> 在头之间共享键值；本课沿深度共享：若干层用同一组 \\(K,V\\)，各层只保留自己的 \\(Q\\)。这是 Cross-Layer Attention（CLA）。下一课 YOCO 会把「只缓存一次」推到整网尺度；本课先做相邻层捆绑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归解码时，每层每个 KV 头每步追加一条 \\(d_k\\) 维向量。<a href="/llm/gqa">GQA</a> 把头数从 \\(n_h\\) 收到 \\(n_{kv}\\)，缓存乘子变成 \\(n_{kv}/n_h\\)。深度 \\(L\\) 仍在。72 层模型即便 GQA 激进，仍然是 72 份时间序列。缺口是：<strong>沿层复用键值</strong>，让缓存从 \\(\\Theta(L)\\) 降到 \\(\\Theta(L/g)\\)，\\(g\\) 为共享组大小，同时尽量不毁掉各层查询已经学到的读模式。</p><p>共享权重里的 ALBERT 把整层参数绑死，下一单元会写；CLA 只绑 KV 投影的输出，注意力权重与 FFN 仍按层独立。对象不同。</p><p><span class="marginnote">MLA 压缩的是头内的潜在维，CLA 压缩的是层维。二者正交，可以叠，本课不展开 MLA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 \\(L\\) 层分成宽度 \\(g\\) 的组（常 \\(g=2\\) 或 \\(4\\)）。组内第一层照常算 \\(K,V\\) 并写入缓存；后续层只算 \\(Q\\)，对组内那份 \\(K,V\\) 做 <a href="/llm/sdpa">SDPA</a>。实现上缓存下标按组走，而不是按层走。训练必须从一开始就共享，或从稠密 KV 的检查点做短对齐：若先按层独立训再突然共用，查询与键空间会对不齐。</p><p>查询仍按层，是因为各层残差流内容不同，需要不同的读角度去看<strong>同一份</strong>记忆。这与 GQA「多套查询看同一套头」同构，只是共享轴从头换成层。</p><h3 id="组的切法" tabindex="-1">组的切法 <a class="header-anchor" href="#组的切法" aria-label="Permalink to &quot;组的切法&quot;">​</a></h3><p>相邻层共享最常见，因为表示变化连续。隔层共享、只让浅层出 KV 深层只读，是 YOCO 的方向，本课不提前用。\\(g\\) 越大省得越多，深层查询看到的记忆越「浅」——键来自更早的残差流。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>KV 缓存存的是「过去写了什么」，不是「当前想读什么」。若相邻层要检索的事实差不多，重复存是浪费。CLA 赌的是：层间读模式可迁移，写模式可复用。训练时查询层会把梯度回传到共享的 \\(W^K,W^V\\)，键空间被组内所有查询共同塑造，类似 GQA 里多个查询头共同塑造较少的 KV 头。</p><p>质量跌点通常出现在组边界：新组的第一层要重新建立记忆，与上一组的键空间断裂。把组对齐到残差变化剧烈的深度（例如每 \\(g\\) 层）比随机捆绑稳。</p><p><span class="marginnote">推理时省的是容量与带宽；训练时仍要算各组的 \\(K,V\\)，省得不多。CLA 是解码内存技术，不是预训练 FLOPs 技术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(g\\) 不是免费旋钮。过大时深层等于在读浅层记忆，长程依赖与复杂推理会掉。与检查点、投机解码、前缀缓存的索引约定都按「层号」写的系统要改元数据，否则会读错组。不要和「把浅层 KV 丢掉」的 eviction 混为一谈：CLA 是训练时的共享，eviction 是推理时的丢弃。</p>',18)),(r(),A(p,null,{default:t(()=>[h(n,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E5%B1%821%20%E7%AE%97%20QKV%22%5D%20--%3E%20KV%5B%22%E5%85%B1%E4%BA%AB%20KV%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20L2%5B%22%E5%B1%822%20%E5%8F%AA%E7%AE%97%20Q%22%5D%20--%3E%20SDPA%5B%22SDPA%22%5D%0A%20%20KV%20--%3E%20SDPA%0A%20%20L3%5B%22%E5%B1%823%20%E7%AE%97%20QKV%22%5D%20--%3E%20KV2%5B%22%E4%B8%8B%E4%B8%80%E7%BB%84%20KV%22%5D%0A%20%20L4%5B%22%E5%B1%824%20%E5%8F%AA%E7%AE%97%20Q%22%5D%20--%3E%20SDPA2%5B%22SDPA%22%5D%0A%20%20KV2%20--%3E%20SDPA2%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"CLA 沿深度共享键值、按层保留查询，把 KV 缓存从层数线性降到组数线性。"),e("li",null,"训练需按共享结构进行；查询共同塑造一份键空间，类似 GQA 换了轴。"),e("li",null,"省的是解码内存与带宽，不是训练 FLOPs。"),e("li",null,"组过大等于让深层读浅记忆；与 eviction、MLA 不是同一机制。"),e("li",null,"出处：Brandon et al., 2024。")],-1))])}const g=o(c,[["render",m]]);export{f as __pageData,g as default};
